/*
 * Generate `app/types/contract.ts` from `contract/openapi.yaml`.
 *
 * **The generated file is not committed, so this has to be the thing that cannot quietly
 * not happen.** It runs on install and ahead of `dev`, `build`, `generate`, `typecheck`,
 * `lint` and `test` — see `package.json`. Those are wired by prefixing each script rather
 * than through pnpm's `pre`/`post` hooks, because `enable-pre-post-scripts` has changed
 * default between pnpm versions and a hook that silently stops running is the exact
 * failure this change exists to remove.
 *
 * **It deletes the output before it writes, and that ordering is the point.** A generator
 * that fails after the file already exists leaves the previous one in place, and the build
 * then succeeds against a stale copy of a contract that has moved — which is worse than
 * committing the file, because at least a committed file shows up in a diff. Removing it
 * first means a failure leaves nothing to fall back to and the next command fails too.
 *
 * Run directly to regenerate by hand:
 *
 *     node scripts/contract-types.mjs
 */

import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, rmSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const web = resolve(here, '..')

/** The contract, which is the one source for these types. */
const CONTRACT = resolve(web, '../contract/openapi.yaml')

/** Where the generated module goes. Git ignores it. */
const OUTPUT = resolve(web, 'app/types/contract.ts')

/**
 * What openapi-typescript writes at the top of what it generates.
 *
 * Checked after the fact so that a generator which exits 0 having written something
 * unusable is still caught. "It ran" and "it produced the types" are different claims.
 */
const BANNER = 'auto-generated by openapi-typescript'

/** Stop, with something a reader can act on. */
function fail(message) {
  console.error(`\ncontract types: ${message}\n`)
  process.exit(1)
}

/*
 * **First, before anything that can fail.** The invariant this buys is worth stating: if
 * this script did not finish, there is no output file. Checking the contract first and
 * deleting afterwards would leave yesterday's types on disk when the contract goes
 * missing — which is the stale fallback this whole arrangement exists to make impossible.
 */
rmSync(OUTPUT, { force: true })

if (!existsSync(CONTRACT)) {
  fail(
    `the contract is not at ${CONTRACT}.\n`
    + '  `app/types/contract.ts` is generated from it and is deliberately not committed,\n'
    + '  so there is nothing to fall back on. Check out the whole repository rather than\n'
    + '  the `web` directory on its own.',
  )
}

try {
  execFileSync(
    'openapi-typescript',
    [CONTRACT, '-o', OUTPUT],
    { cwd: web, stdio: ['ignore', 'inherit', 'inherit'], env: process.env },
  )
}
catch (error) {
  fail(
    `openapi-typescript failed: ${error.message}\n`
    + '  Nothing was written, and the previous output has been removed, so no build will\n'
    + '  run against a stale copy of the contract.',
  )
}

if (!existsSync(OUTPUT)) {
  fail('openapi-typescript reported success but wrote no file.')
}

if (!readFileSync(OUTPUT, 'utf8').includes(BANNER)) {
  fail(
    `${OUTPUT} does not look like generated output.\n`
    + '  It is rewritten on every install and before every build, so anything edited by\n'
    + '  hand there is lost. The types come from `contract/openapi.yaml`.',
  )
}
